 p jsonb; old_rows jsonb; remaining_rows jsonb; n integer;
BEGIN
 IF md5(raw_payload) <> '116446ea1648675bb7b6a5a81fc2b96b' THEN RAISE EXCEPTION 'PAYLOAD_HASH_MISMATCH'; END IF;
 p:=raw_payload::jsonb;
 IF jsonb_array_length(p)<>22 THEN RAISE EXCEPTION 'COUNT_GATE'; END IF;
 IF current_user<>'postgres' OR current_database()<>'postgres' THEN RAISE EXCEPTION 'EXECUTOR_GATE'; END IF;
 IF (SELECT count(*) FROM public.restaurants)<>438 OR (SELECT count(*) FROM public.restaurants WHERE status='published')<>436 THEN RAISE EXCEPTION 'BASELINE_DRIFT'; END IF;
 IF (SELECT count(*) FROM pg_index WHERE indrelid='public.restaurants'::regclass AND indisunique AND indisvalid AND indisready)<>3 THEN RAISE EXCEPTION 'UNIQUE_INDEX_GATE'; END IF;
 IF EXISTS(SELECT 1 FROM pg_index WHERE indrelid='public.restaurants'::regclass AND NOT(indisvalid AND indisready)) THEN RAISE EXCEPTION 'INVALID_INDEX'; END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.restaurants'::regclass AND NOT tgisinternal)<>1 OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.restaurants'::regclass AND NOT tgisinternal AND (tgname<>'restaurants_set_updated_at' OR (tgtype::int & 4)>0 OR (tgtype::int & 8)>0)) THEN RAISE EXCEPTION 'TRIGGER_DRIFT'; END IF;
 IF (SELECT count(*) FROM pg_constraint WHERE contype='f' AND confrelid='public.restaurants'::regclass)<>4 THEN RAISE EXCEPTION 'DEPENDENCY_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p) x WHERE x->>'status'<>'published' OR x->>'city'<>'Cuiabá' OR x->>'country_code'<>'BR' OR (x->>'accepts_duo_gourmet')::boolean IS DISTINCT FROM true OR x->>'duo_gourmet_checked_at' IS NULL OR x->>'google_place_id' IS NULL OR x->>'price_range' IS NOT NULL OR x->>'cover_photo_url' IS NOT NULL OR x->>'cover_photo_path' IS NOT NULL) THEN RAISE EXCEPTION 'PAYLOAD_QUALITY_GATE'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p) x JOIN public.restaurants r ON r.id=(x->>'id')::uuid OR r.slug=x->>'slug' OR r.google_place_id=x->>'google_place_id' OR lower(r.city) IN ('cuiabá','cuiaba') OR (abs(r.latitude-(x->>'latitude')::float8)<0.02 AND abs(r.longitude-(x->>'longitude')::float8)<0.02) OR lower(r.name)=lower(x->>'name')) THEN RAISE EXCEPTION 'EXACT_OR_SECONDARY_COLLISION'; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO old_rows FROM public.restaurants r;
 INSERT INTO public.restaurants (id,slug,name,address,city,neighborhood,latitude,longitude,category,cuisines,price_range,chef,google_place_id,country_code,accepts_duo_gourmet,duo_gourmet_checked_at,status,cover_photo_url,cover_photo_path) SELECT id,slug,name,address,city,neighborhood,latitude,longitude,category,cuisines,price_range,chef,google_place_id,country_code,accepts_duo_gourmet,duo_gourmet_checked_at,status,cover_photo_url,cover_photo_path FROM jsonb_populate_recordset(NULL::public.restaurants,p);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>22 THEN RAISE EXCEPTION 'INSERT_COUNT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p) x LEFT JOIN public.restaurants r ON r.id=(x->>'id')::uuid WHERE r.id IS NULL OR NOT(to_jsonb(r) @> (x-'duo_gourmet_checked_at'-'latitude'-'longitude')) OR r.latitude IS DISTINCT FROM (x->>'latitude')::float8 OR r.longitude IS DISTINCT FROM (x->>'longitude')::float8 OR r.duo_gourmet_checked_at IS DISTINCT FROM (x->>'duo_gourmet_checked_at')::timestamptz) THEN RAISE EXCEPTION 'READBACK_MISMATCH'; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO remaining_rows FROM public.restaurants r WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p) x WHERE r.id=(x->>'id')::uuid);
 IF old_rows IS DISTINCT FROM remaining_rows THEN RAISE EXCEPTION 'EXISTING_ROWS_CHANGED'; END IF;
 IF (SELECT count(*) FROM public.restaurants WHERE status='published')<>458 OR (SELECT count(*) FROM public.restaurants)<>460 THEN RAISE EXCEPTION 'AFTER_COUNT'; END IF;
 IF EXISTS(SELECT google_place_id FROM public.restaurants WHERE google_place_id IS NOT NULL GROUP BY google_place_id HAVING count(*)>1) OR EXISTS(SELECT slug FROM public.restaurants GROUP BY slug HAVING count(*)>1) THEN RAISE EXCEPTION 'DUPLICATE_AFTER'; END IF;
 IF EXISTS(SELECT 1 FROM public.reviews WHERE restaurant_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(p) x)) OR EXISTS(SELECT 1 FROM public.restaurant_list_items WHERE restaurant_id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(p) x)) THEN RAISE EXCEPTION 'UNEXPECTED_ACTIVITY'; END IF;
END $gate$;
COMMIT;
SELECT 'duo-cuiaba-2026-09' AS batch, count(*) AS inserted, count(*) FILTER(WHERE status='published') AS published, count(*) FILTER(WHERE accepts_duo_gourmet) AS duo_true, count(duo_gourmet_checked_at) AS checked_at, count(DISTINCT google_place_id) AS distinct_place_ids, (SELECT count(*) FROM public.restaurants WHERE status='published') AS database_published, jsonb_agg(id ORDER BY id) AS batch_ids FROM public.restaurants WHERE id IN ('9dfa5906-33c9-5d94-9332-64606fefc9af','324ee833-dd86-5222-bae6-3441d8db34f5','4c31b41d-94c6-5bf5-aeeb-138d310c92df','a498bb22-2571-50ab-9268-601ed30d621e','1e592c62-f22c-5892-8a5f-299c46024c16','f70333a5-48bb-5823-b655-1420b73ee403','9e15d9bc-a75a-59f3-b789-b314de5acafd','e550f1f3-5c49-5941-a132-8baa35a774b0','79129cdd-29fb-547e-b500-b192e0e38396','8fea3083-03b7-5933-b23c-c7684a542995','62339e3f-19d0-53fb-aa0d-eb6f7bb800c9','0a750d62-c256-50b2-80aa-6b8084aadf94','507cd4cb-8cc1-5d81-b8fc-38afc0814995','d8c84394-2a2c-5bdf-adf2-402c00259f87','2795da10-8404-51c7-b4c0-8b9bdcb305e4','3cb67d58-861b-51b2-a95b-59d5d2d08a0f','f5cff15f-b957-5902-b309-418d4d828d40','218103c8-80cf-5c97-a7f4-905ec110754f','c1ba3ae1-d1fd-5812-ba3e-f88f54e8d824','04970fb3-67b7-5218-8f54-982937496099','3abfa8f3-e146-5493-b10a-25d785bdd5d5','3db1cd0f-4f0e-5b8c-9c7c-a39910a0014d');
